use std::sync::Arc;
use std::thread;
fn main() {
    let message = Arc::new(String::from("sensor ready"));
    let worker_message = Arc::clone(&message);
    let worker = thread::spawn(move || worker_message.len());
    match worker.join() {
        Ok(length) => println!("{} {length}", message.as_str()),
        Err(_) => eprintln!("worker panicked"),
    };
}
